class Solution { public int regionsBySlashes(String[] grid){int n=grid.length,size=3*n;boolean[][] blocked=new boolean[size][size];for(int r=0;r<n;r++)for(int c=0;c<n;c++){char ch=grid[r].charAt(c);if(ch=='/'){blocked[3*r][3*c+2]=blocked[3*r+1][3*c+1]=blocked[3*r+2][3*c]=true;}else if(ch==92){blocked[3*r][3*c]=blocked[3*r+1][3*c+1]=blocked[3*r+2][3*c+2]=true;}}int regions=0;int[][] directions={{1,0},{-1,0},{0,1},{0,-1}};for(int r=0;r<size;r++)for(int c=0;c<size;c++)if(!blocked[r][c]){regions++;Deque<int[]> queue=new ArrayDeque<>();queue.offer(new int[]{r,c});blocked[r][c]=true;while(!queue.isEmpty()){int[] cell=queue.poll();for(int[] d:directions){int nr=cell[0]+d[0],nc=cell[1]+d[1];if(nr>=0&&nr<size&&nc>=0&&nc<size&&!blocked[nr][nc]){blocked[nr][nc]=true;queue.offer(new int[]{nr,nc});}}}}return regions;} }
